const variants = {
  enter: (dir: number) => ({ opacity: 0, x: dir * 48 }),
  center: { opacity: 1, x: 0 },
  exit: (dir: number) => ({ opacity: 0, x: dir * -48 }),
};

export default function ZachraneniList() {
  const [idx, setIdx] = useState(0);
  const [dir, setDir] = useState(1);

  const go = useCallback(
    (next: number) => {
      if (next < 0 || next >= cases.length) return;
      setDir(next > idx ? 1 : -1);
      setIdx(next);
    },
    [idx]
  );

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "ArrowRight") go(idx + 1);
      if (e.key === "ArrowLeft") go(idx - 1);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [idx, go]);

  const c = cases[idx];

  return (
    <div className="mx-auto max-w-5xl px-6 pt-8 pb-28">

      {/* Header */}
      <motion.div
        className="text-center mb-8"
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.55, ease: [0.16, 1, 0.3, 1] }}
      >
        <h1 className="text-5xl md:text-6xl font-bold tracking-tight">Zachránení</h1>
      </motion.div>

      {/* Mobile navigation — above the story so it's always visible */}
      <div className="flex md:hidden items-center justify-between mb-6 gap-4">
        <button
          onClick={() => go(idx - 1)}
          disabled={idx === 0}
          className="flex items-center gap-2 rounded-2xl px-4 py-2.5 text-sm font-medium border border-white/15 hover:border-white/35 hover:bg-white/5 transition-all disabled:opacity-25 disabled:pointer-events-none cursor-pointer"
        >
          <svg viewBox="0 0 16 16" className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth="1.8">
            <path strokeLinecap="round" strokeLinejoin="round" d="M10 12L6 8l4-4" />
          </svg>
          Predošlé
        </button>

        <span className="text-sm text-white/35 tabular-nums font-medium">{idx + 1} / {cases.length}</span>

        <button
          onClick={() => go(idx + 1)}
          disabled={idx === cases.length - 1}
          className="flex items-center gap-2 rounded-2xl px-4 py-2.5 text-sm font-medium border border-white/15 hover:border-white/35 hover:bg-white/5 transition-all disabled:opacity-25 disabled:pointer-events-none cursor-pointer"
        >
          Ďalšie
          <svg viewBox="0 0 16 16" className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth="1.8">
            <path strokeLinecap="round" strokeLinejoin="round" d="M6 4l4 4-4 4" />
          </svg>
        </button>
      </div>

      {/* Story */}
      <div className="overflow-hidden">
        <AnimatePresence mode="wait" custom={dir}>
          <motion.div
            key={idx}
            custom={dir}
            variants={variants}
            initial="enter"
            animate="center"
            exit="exit"
            transition={{ duration: 0.38, ease: [0.16, 1, 0.3, 1] }}
            className="flex flex-col md:flex-row gap-10 md:gap-12 items-start"
          >
            {/* Photo */}
            <div className="relative w-full aspect-[4/3] md:w-[44%] md:aspect-[3/4] rounded-2xl overflow-hidden shrink-0 bg-white/5">
              <div
                className="absolute inset-0"
                style={c.zoom ? { transform: `scale(${1 + parseInt(c.zoom) / 100})` } : undefined}
              >
                <Image
                  src={c.image}
                  alt={c.name}
                  fill
                  sizes="(max-width: 768px) 100vw, 44vw"
                  className="object-cover"
                  style={{ objectPosition: c.imgPos ?? "center" }}
                  priority
                />
              </div>
            </div>

            {/* Text */}
            <div className="flex-1 min-w-0 flex flex-col">
              <p className="text-white/30 text-sm shrink-0">
                {c.date}&ensp;·&ensp;{c.location}
              </p>
              <h2 className="mt-2 text-4xl md:text-5xl font-bold tracking-tight leading-none shrink-0">
                {c.name}
              </h2>
              <p className="mt-2 text-white/35 text-sm shrink-0">{c.animal}</p>

              <div className="mt-6 space-y-4 text-white/65 text-[15px] leading-[1.85]">
                {c.story.map((paragraph, pi) => (
                  <p key={pi}>{paragraph}</p>
                ))}
              </div>
            </div>
          </motion.div>
        </AnimatePresence>
      </div>

      {/* Desktop navigation — with dot indicators */}
      <div className="mt-14 hidden md:flex items-center justify-between gap-4">
        <button
          onClick={() => go(idx - 1)}
          disabled={idx === 0}
          className="flex items-center gap-2.5 rounded-2xl px-5 py-3 text-sm font-medium border border-white/15 hover:border-white/35 hover:bg-white/5 transition-all disabled:opacity-25 disabled:pointer-events-none cursor-pointer"
        >
          <svg viewBox="0 0 16 16" className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth="1.8">
            <path strokeLinecap="round" strokeLinejoin="round" d="M10 12L6 8l4-4" />
          </svg>
          Predošlé
        </button>

        <div className="flex items-center gap-1.5">
          {cases.map((_, i) => (
            <button
              key={i}
              onClick={() => go(i)}
              className={[
                "cursor-pointer rounded-full transition-all duration-300",
                i === idx
                  ? "w-5 h-2 bg-white"
                  : "w-2 h-2 bg-white/20 hover:bg-white/45",
              ].join(" ")}
              aria-label={`Príbeh ${i + 1}`}
            />
          ))}
        </div>

        <button
          onClick={() => go(idx + 1)}
          disabled={idx === cases.length - 1}
          className="flex items-center gap-2.5 rounded-2xl px-5 py-3 text-sm font-medium border border-white/15 hover:border-white/35 hover:bg-white/5 transition-all disabled:opacity-25 disabled:pointer-events-none cursor-pointer"
        >
          Ďalšie
          <svg viewBox="0 0 16 16" className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth="1.8">
            <path strokeLinecap="round" strokeLinejoin="round" d="M6 4l4 4-4 4" />
          </svg>
        </button>
      </div>
    </div>
  );
}
